//! CPython 3.11 single-character string predicates (Unicode 14.0), from tables generated by
//! `tools/gen_unicode_tables.py`. Rust's `char::is_alphabetic` / `is_alphanumeric` use different Unicode
//! properties (e.g. they include combining marks), so they cannot be used for parity.

use std::cmp::Ordering;

use crate::unicode_tables::{ALNUM, ALPHA, LOWER, UPPER};

fn contains(table: &[(u32, u32)], c: char) -> bool {
    let cp = c as u32;
    table
        .binary_search_by(|&(lo, hi)| {
            if hi < cp {
                Ordering::Less
            } else if lo > cp {
                Ordering::Greater
            } else {
                Ordering::Equal
            }
        })
        .is_ok()
}

/// Python `c.isalpha()` (General Category Lu/Ll/Lt/Lm/Lo).
pub fn py_isalpha(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphabetic();
    }
    contains(&ALPHA, c)
}

/// Python `c.isalnum()`.
pub fn py_isalnum(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric();
    }
    contains(&ALNUM, c)
}

/// Python `c.isupper()` for one character.
pub fn py_isupper(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_uppercase();
    }
    contains(&UPPER, c)
}

/// Python `c.islower()` for one character.
pub fn py_islower(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_lowercase();
    }
    contains(&LOWER, c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_and_disjoint() {
        for table in [&ALPHA[..], &ALNUM[..], &UPPER[..], &LOWER[..]] {
            for pair in table.windows(2) {
                assert!(pair[0].0 <= pair[0].1 && pair[0].1 < pair[1].0);
            }
        }
    }

    #[test]
    fn ascii_fast_path_matches_tables() {
        for b in 0u8..128 {
            let c = b as char;
            assert_eq!(py_isalpha(c), contains(&ALPHA, c));
            assert_eq!(py_isalnum(c), contains(&ALNUM, c));
            assert_eq!(py_isupper(c), contains(&UPPER, c));
            assert_eq!(py_islower(c), contains(&LOWER, c));
        }
    }

    #[test]
    fn known_characters() {
        assert!(py_isalpha('ş') && py_isalpha('中') && !py_isalpha('\u{0903}') && !py_isalpha('Ⅻ'));
        assert!(py_isalnum('Ⅻ') && py_isalnum('٣') && py_isalnum('½') && !py_isalnum('-'));
        assert!(py_isupper('İ') && py_islower('ı') && !py_isupper('中') && !py_islower('中'));
        assert!(!py_isupper('\u{01C5}') && !py_islower('\u{01C5}'));
    }
}
